else{try{$s=db()->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);$id=(int)db()->lastInsertId();if($role==='talent')db()->prepare('INSERT INTO talent_profiles(user_id) VALUES(?)')->execute([$id]);session_regenerate_id(true);$_SESSION['user_id']=$id;header('Location: '.url('dashboard.php'));exit;}catch(PDOException $e){$error='That email is already registered.';}}}
